#!/bin/bash
perl -0777 -pi -e 's/import com.silentpdf.app.ui.screens.PinLockScreen/import com.silentpdf.app.ui.screens.PinLockScreen\nimport com.silentpdf.app.ui.screens.OnboardingScreen\nimport android.os.Build\nimport com.google.accompanist.permissions.ExperimentalPermissionsApi\nimport com.google.accompanist.permissions.rememberMultiplePermissionsState\nimport androidx.compose.runtime.LaunchedEffect/g' app/src/main/java/com/silentpdf/app/MainActivity.kt

perl -0777 -pi -e 's/\@Composable\nfun SilentPdfApp\(viewModel: SilentPdfViewModel = viewModel\(\)\) \{/\@OptIn(ExperimentalPermissionsApi::class)\n\@Composable\nfun SilentPdfApp(viewModel: SilentPdfViewModel = viewModel()) {\n    val permissions = mutableListOf(\n        android.Manifest.permission.CAMERA\n    )\n    if (Build.VERSION.SDK_INT <= Build.VERSION.CODES.TIRAMISU) {\n        permissions.add(android.Manifest.permission.READ_EXTERNAL_STORAGE)\n    }\n    val permissionState = rememberMultiplePermissionsState(permissions)\n    val startDest = if (permissionState.allPermissionsGranted) "library" else "onboarding"/g' app/src/main/java/com/silentpdf/app/MainActivity.kt

perl -0777 -pi -e 's/startDestination = "library"/startDestination = startDest/g' app/src/main/java/com/silentpdf/app/MainActivity.kt

perl -0777 -pi -e 's/composable\("library"\) \{/composable("onboarding") {\n                    OnboardingScreen(\n                        viewModel = viewModel,\n                        onNavigateToLibrary = {\n                            navController.navigate("library") {\n                                popUpTo("onboarding") { inclusive = true }\n                            }\n                        }\n                    )\n                }\n                composable("library") {/g' app/src/main/java/com/silentpdf/app/MainActivity.kt
